/// write statements on a corrupt index: xSavepoint / xRelease and a repeated flush (`flushRc`) report the bare code (`database disk image is malformed`), xUpdate / xFilter / xSync the fts5 message; changes() and total_changes() after every failed statement are those of C (0 after a refused shadow statement: SQLITE_CorruptRdOnly).
#[test]
fn fts5_writes_on_a_corrupt_index_messages_and_changes() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_writes_on_a_corrupt_index_messages_and_changes",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('one two', 'three'), ('two four', 'five'), ('six', 'one seven');",
            "INSERT INTO ft(ft, rank) VALUES('crisismerge', 2);",
            "UPDATE ft_data SET block = X'00000000' WHERE id = 137438953473;",
            "BEGIN;",
            "INSERT INTO ft VALUES('eight', 'nine');",
            "SELECT 'a', changes(), total_changes();",
            "SAVEPOINT s1;",
            "SELECT 'b', changes(), total_changes();",
            "INSERT INTO ft VALUES('ten', 'eleven');",
            "SELECT 'c', changes(), total_changes();",
            "DELETE FROM ft WHERE rowid = 1;",
            "SELECT 'd', changes(), total_changes();",
            "UPDATE ft SET a = 'x' WHERE rowid = 2;",
            "SELECT 'e', changes(), total_changes();",
            "SELECT rowid FROM ft WHERE ft MATCH 'two';",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('six');",
            "RELEASE s1;",
            "SELECT 'f', changes(), total_changes();",
            "COMMIT;",
            "SELECT 'g', changes(), total_changes();",
            "SELECT count(*) FROM ft;",
            "ROLLBACK;",
            "SELECT count(*) FROM ft_content;",
            "BEGIN;",
            "INSERT INTO ft VALUES('twelve', 'x');",
            "INSERT INTO ft VALUES('thirteen', 'y');",
            "SELECT 'h', changes(), total_changes();",
            "DELETE FROM ft WHERE rowid = 3;",
            "SELECT 'i', changes(), total_changes();",
            "UPDATE ft SET b = 'q' WHERE rowid = 2;",
            "SELECT 'j', changes(), total_changes();",
            "INSERT INTO ft VALUES('fourteen', 'z');",
            "SELECT 'k', changes(), total_changes();",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('two');",
            "COMMIT;",
            "SELECT 'l', changes(), total_changes();",
            "SELECT count(*) FROM ft_content;",
            "SELECT hex(block) FROM ft_data WHERE id = 1;",
        ],
        "a|1|22\nb|1|25\nc|1|28\nd|0|28\ne|1|33\nf|1|33\ng|1|34\n3\n3\nh|1|40\ni|0|42\nj|0|42\nk|1|45\nl|1|46\n3\n030504\n",
        &[
            "database disk image is malformed",
            "database disk image is malformed",
            "fts5: corruption found reading blob 137438953473 from table \"ft\"",
            "fts5: corruption found reading blob 137438953473 from table \"ft\"",
            "no such savepoint: s1",
            "database disk image is malformed",
            "cannot rollback - no transaction is active",
            "fts5: corruption found reading blob 137438953473 from table \"ft\"",
            "database disk image is malformed",
            "fts5: corruption found reading blob 137438953473 from table \"ft\"",
            "database disk image is malformed",
        ],
    );
}

/// a transaction that goes on after failed statements on a corrupt index: bm25 values (in-memory totals), counts, the message of the failing DELETE (xUpdate) and of COMMIT (flushRc: bare code).
#[test]
fn fts5_totals_and_messages_after_failed_statements_in_a_transaction() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_totals_and_messages_after_failed_statements_in_a_transaction",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a);",
            "INSERT INTO ft(ft, rank) VALUES('pgsz', 32);",
            "INSERT INTO ft(ft, rank) VALUES('crisismerge', 3);",
            "WITH RECURSIVE c(i) AS (SELECT 1 UNION ALL SELECT i+1 FROM c WHERE i<40) INSERT INTO ft(rowid, a) SELECT i, 'aaa' || (i%3) || ' mmm' || i || ' zzz' || (i%5) FROM c;",
            "SELECT count(*), max(id) FROM ft_data WHERE id >= 137438953472 AND id < 137438953472 + 2147483648;",
            "UPDATE ft_data SET block = X'00000000' WHERE id = (SELECT max(id) FROM ft_data WHERE id >= 137438953472 AND id < 137438953472 + 2147483648);",
            "BEGIN;",
            "INSERT INTO ft(rowid, a) VALUES(100, 'aaa1 new');",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('aaa1') ORDER BY rowid LIMIT 3;",
            "UPDATE ft SET a = 'aaa1 changed' WHERE rowid = 4;",
            "SELECT 'a', changes(), total_changes();",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('aaa1') ORDER BY rowid LIMIT 3;",
            "INSERT INTO ft(rowid, a) VALUES(101, 'aaa1 more');",
            "SELECT 'b', changes(), total_changes();",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('aaa1') ORDER BY rowid LIMIT 3;",
            "DELETE FROM ft WHERE rowid = 7;",
            "SELECT 'c', changes(), total_changes();",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('aaa1') ORDER BY rowid LIMIT 3;",
            "SELECT count(*) FROM ft WHERE ft MATCH 'aaa1';",
            "COMMIT;",
            "SELECT 'd', changes(), total_changes();",
            "SELECT count(*) FROM ft_content;",
            "SELECT hex(block) FROM ft_data WHERE id = 1;",
            "SELECT rowid, printf('%.9g', bm25(ft)) FROM ft('aaa1') ORDER BY rowid LIMIT 3;",
        ],
        "25|137438953497\n1|-0.53451238\n4|-0.53451238\n7|-0.53451238\na|1|187\n1|-0.532702663\n4|-0.617759903\n7|-0.532702663\nb|1|190\n1|-0.469103716\n4|-0.544399345\n7|-0.469103716\nc|0|239\n1|-0.469103716\n4|-0.544399345\n7|-0.469103716\n16\nd|1|240\n40\n2878\n1|-0.602996084\n4|-0.602996084\n7|-0.602996084\n",
        &[
            "fts5: corruption found reading blob 137438953497 from table \"ft\"",
            "database disk image is malformed",
        ],
    );
}

/// UPDATE through a MATCH cursor reads the rank column (see the file test): messages, changes() and rows after each statement.
#[test]
fn fts5_update_scan_reads_the_rank_column_rows() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_update_scan_reads_the_rank_column_rows",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta'), ('hello there world', 'beta gamma'), ('goodbye world', 'gamma delta hello'), ('one two three', 'x y z');",
            "UPDATE ft SET b = 'u1' WHERE ft MATCH 'hello' AND rowid < 3;",
            "SELECT rowid, a, b FROM ft;",
            "DELETE FROM ft_docsize WHERE id = 2;",
            "UPDATE ft SET b = 'u2' WHERE ft MATCH 'world';",
            "SELECT changes(), total_changes();",
            "SELECT rowid, a, b FROM ft;",
            "UPDATE ft SET b = 'u3' WHERE rowid = 2;",
            "SELECT changes();",
            "SELECT rowid, a, b FROM ft;",
            "UPDATE ft SET a = 'x' WHERE ft MATCH 'world' AND rank MATCH 'nosuchfn()';",
            "UPDATE ft SET a = 'y y' WHERE ft MATCH 'gamma' AND rank MATCH 'bm25(10.0, 1.0)';",
            "SELECT rowid, a, b FROM ft;",
            "DELETE FROM ft WHERE ft MATCH 'world';",
            "SELECT changes();",
            "SELECT rowid, a, b FROM ft;",
            "INSERT INTO ft(ft) VALUES('integrity-check');",
        ],
        "1|hello world one two|u1\n2|hello there world|u1\n3|goodbye world|gamma delta hello\n4|one two three|x y z\n0|34\n1|hello world one two|u1\n2|hello there world|u1\n3|goodbye world|gamma delta hello\n4|one two three|x y z\n1\n1|hello world one two|u1\n2|hello there world|u3\n3|goodbye world|gamma delta hello\n4|one two three|x y z\n1|hello world one two|u1\n2|hello there world|u3\n3|y y|gamma delta hello\n4|one two three|x y z\n2\n3|y y|gamma delta hello\n4|one two three|x y z\n",
        &[
            "database disk image is malformed",
            "no such function: nosuchfn",
        ],
    );
}

/// UPDATE of a contentless_unindexed=1 table keeps the unassigned UNINDEXED columns (see the file test): rows, %_content, the subset-of-columns error, integrity-check.
#[test]
fn fts5_contentless_unindexed_update_keeps_unassigned_columns_rows() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_contentless_unindexed_update_keeps_unassigned_columns_rows",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b UNINDEXED, c, content='', contentless_delete=1, contentless_unindexed=1);",
            "INSERT INTO ft(rowid, a, b, c) VALUES(1, 'one two', 'keep me', 'x y'), (2, 'three', 'other', 'z'), (3, 'four', NULL, 'w');",
            "UPDATE ft SET a = 'four five', c = 'q' WHERE rowid = 1;",
            "SELECT rowid, b FROM ft;",
            "SELECT * FROM ft_content ORDER BY id;",
            "UPDATE ft SET b = 'changed' WHERE rowid = 2;",
            "SELECT rowid, b FROM ft;",
            "SELECT rowid FROM ft('four');",
            "UPDATE ft SET rowid = 9, a = 'six', c = 'r' WHERE rowid = 1;",
            "UPDATE OR REPLACE ft SET rowid = 2, a = 'seven', c = 's' WHERE rowid = 3;",
            "UPDATE ft SET a = 'eight' WHERE rowid = 9;",
            "SELECT * FROM ft_content ORDER BY id;",
            "SELECT rowid, b FROM ft WHERE ft MATCH 'six OR seven OR three OR four';",
            "SELECT changes(), total_changes();",
            "INSERT INTO ft(ft) VALUES('integrity-check');",
        ],
        "1|keep me\n2|other\n3|\n1|keep me\n2|other\n3|\n1|keep me\n2|changed\n3|\n1\n3\n2|\n9|keep me\n2|\n9|keep me\n0|54\n",
        &[
            "cannot UPDATE a subset of columns on fts5 contentless-delete table: ft",
        ],
    );
}

/// tables of modules without xUpdate (fts5vocab, dbstat, pragma functions, generate_series, json_each): `table X may not be modified` as an SQLITE_ERROR of the parser for INSERT / UPDATE / DELETE; it wins over the RETURNING restriction; no-such-column errors come after it.
#[test]
fn vtab_without_xupdate_is_read_only_when_prepared() {
    assert_rows_and_errors_are_what_c_returns(
        "vtab_without_xupdate_is_read_only_when_prepared",
        &[
            "DELETE FROM pragma_database_list;",
            "UPDATE pragma_database_list SET name = 1;",
            "INSERT INTO pragma_database_list VALUES(1,2,3);",
            "DELETE FROM generate_series;",
            "INSERT INTO dbstat(name) VALUES(1);",
            "DELETE FROM json_each WHERE 0;",
            "CREATE VIRTUAL TABLE ft USING fts5(a);",
            "CREATE VIRTUAL TABLE vr USING fts5vocab(ft, row);",
            "INSERT INTO vr VALUES(1,2,3);",
            "UPDATE vr SET term=1 WHERE 0;",
            "SELECT count(*) FROM vr;",
            "CREATE VIRTUAL TABLE ft USING fts5(a);",
            "CREATE VIRTUAL TABLE vr USING fts5vocab(ft, row);",
            "UPDATE vr SET term = 'x' RETURNING term;",
            "DELETE FROM vr RETURNING term;",
            "UPDATE vr SET term = 'x';",
            "DELETE FROM pragma_table_info('ft') RETURNING name;",
            "UPDATE dbstat SET name = 1 RETURNING 1;",
            "INSERT INTO vr VALUES(1,2,3) RETURNING 1;",
            "WITH x AS (SELECT 1) UPDATE ft SET a = 1 RETURNING (SELECT * FROM x);",
            "UPDATE ft SET a = 1 WHERE nosuch = 1 RETURNING 5;",
            "DELETE FROM ft WHERE nosuch MATCH 1 RETURNING *;",
        ],
        "0\n",
        &[
            "table pragma_database_list may not be modified",
            "table pragma_database_list may not be modified",
            "table pragma_database_list may not be modified",
            "table generate_series may not be modified",
            "table dbstat may not be modified",
            "table json_each may not be modified",
            "table vr may not be modified",
            "table vr may not be modified",
            "table ft already exists",
            "table vr already exists",
            "table vr may not be modified",
            "table vr may not be modified",
            "table vr may not be modified",
            "near \"(\": syntax error",
            "table dbstat may not be modified",
            "table vr may not be modified",
            "UPDATE RETURNING is not available on virtual tables",
            "UPDATE RETURNING is not available on virtual tables",
            "DELETE RETURNING is not available on virtual tables",
        ],
    );
}
